import{z as i,x as o,o as B,c as s,q as e,j as A,D as a,d as n,s as r,S as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"缩放的失败模式","description":"","frontmatter":{"title":"缩放的失败模式","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-scaling-failures.md","filePath":"llm/pf2-scaling-failures.md","lastUpdated":1791063341000}'),p={name:"llm/pf2-scaling-failures.md"};function F(h,E,d,m,D,c){const l=o("Mermaid");return B(),s("div",null,[E[2]||(E[2]=e('<h1 id="缩放的失败模式" tabindex="-1">缩放的失败模式 <a class="header-anchor" href="#缩放的失败模式" aria-label="Permalink to &quot;缩放的失败模式&quot;">​</a></h1><div class="epigraph"><p>缩放律是经验拟合，不是定理；缩放事故的大多数，是把一次拟合当成了普适定理来用。</p><footer>—— 据 Hoffmann et al., 2022 对 Kaplan et al., 2020 的修正与后续复现文献整理</footer></div><p><a href="/llm/pf2-model-eval-gates">上一课</a>关上发布门禁，交付链走完。本课在收束段回望整套规划的地基——缩放决策本身——把散落在先修课与前面各课里的错用收成一份失败模式清单。<a href="/llm/kaplan-scaling">Kaplan 的标度律</a>、<a href="/llm/chinchilla">Chinchilla 的修正</a>与<a href="/llm/scaling-law-fitting">拟合方法</a>是正面的；本课写反面：每一类失败怎么发生、怎么在配方里预防。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缩放决策错一次的代价是整代模型的算力：\\(N\\) 与 \\(D\\) 的分割、代理规模的选取、预算里程碑的设定，一旦错了要在数月后以「下一代模型不及预期」的形式显形，而那时账已经烧完。失败之所以反复出现，是因为缩放律的结论常以口诀形式传播——「每参数二十个 token」「大模型更样本高效」——口诀丢掉了原拟合的坐标系与前提，剩下的数字被当成常数使用。清单化失败模式，就是把口诀还原回它的适用范围。</p><p><span class="marginnote">「缩放律」就是拿几十到几百次不同规模的训练结果，拟合出「损失随参数与数据量怎么降」的经验曲线——它像实验物理的拟合公式，在测过的范围内好用，超出范围谁也不担保。</span></p><h3 id="五类失败" tabindex="-1">五类失败 <a class="header-anchor" href="#五类失败" aria-label="Permalink to &quot;五类失败&quot;">​</a></h3><p><strong>一，日程耦合的误读</strong>：Kaplan 时代「偏大模型」的分割部分来自学习率日程与训练长度的耦合——模型在远未训完的日程上被比较；<a href="/llm/hoffmann-chinchilla">Chinchilla</a> 对齐寿命后谷底移向等比。预防：比较前先核对各家日程是否衰减到位。<strong>二，常数化系数</strong>：把 20 token/参数写进脚本；MoE、重复数据、过训目标都会移动谷底，见<a href="/llm/moe-scaling-laws">MoE 标度</a>与<a href="/llm/data-constrained-scaling">数据受限缩放</a>。<strong>三，指标悬崖规划</strong>：用下游准确率的涌现点做买卡里程碑，而准确率悬崖可以是阈值度量造出来的，见<a href="/llm/emergence-debate">涌现之争</a>。<strong>四，代理越界迁移</strong>：小代理结论搬过深度、序列长、词表或优化器的边界，μP 只担保宽度。<strong>五，拟合吃脏点</strong>：用混入 warmup 段、尖峰、SDC 缺口的曲线拟合指数，谷底整体移位。</p>',8)),(B(),A(t,null,{default:a(()=>[r(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20F1%5B%22%E6%97%A5%E7%A8%8B%E8%80%A6%E5%90%88%E8%AF%AF%E8%AF%BB%22%5D%20--%3E%20P1%5B%22%E6%AF%94%E8%BE%83%E5%89%8D%E6%A0%B8%E5%AF%B9%E8%A1%B0%E5%87%8F%E5%88%B0%E4%BD%8D%22%5D%0A%20%20F2%5B%22%E7%B3%BB%E6%95%B0%E5%B8%B8%E6%95%B0%E5%8C%96%22%5D%20--%3E%20P2%5B%22%E8%B0%B7%E5%BA%95%E9%9A%8F%E5%88%B6%E5%BA%A6%E7%A7%BB%E5%8A%A8%EF%BC%8C%E7%B3%BB%E6%95%B0%E9%87%8D%E6%8B%9F%E5%90%88%22%5D%0A%20%20F3%5B%22%E6%8C%87%E6%A0%87%E6%82%AC%E5%B4%96%E8%A7%84%E5%88%92%22%5D%20--%3E%20P3%5B%22%E8%BF%9E%E7%BB%AD%E5%BA%A6%E9%87%8F%E5%A4%8D%E7%94%BB%E5%86%8D%E8%B0%88%E7%9B%B8%E5%8F%98%22%5D%0A%20%20F4%5B%22%E4%BB%A3%E7%90%86%E8%B6%8A%E7%95%8C%E8%BF%81%E7%A7%BB%22%5D%20--%3E%20P4%5B%22coord%20check%20%2B%20%E5%A3%B0%E6%98%8E%E6%8B%85%E4%BF%9D%E8%BE%B9%E7%95%8C%22%5D%0A%20%20F5%5B%22%E6%8B%9F%E5%90%88%E5%90%83%E8%84%8F%E7%82%B9%22%5D%20--%3E%20P5%5B%22%E6%B8%85%E6%B4%97%E6%9B%B2%E7%BA%BF%E6%AE%B5%EF%BC%8C%E4%B8%89%E7%A7%8D%E5%88%87%E7%89%87%E4%BA%A4%E5%8F%89%22%5D%0A%20%20P1%20--%3E%20OK%5B%22%E7%BC%A9%E6%94%BE%E5%86%B3%E7%AD%96%E5%8F%AF%E8%BE%A9%E6%8A%A4%22%5D%0A%20%20P2%20--%3E%20OK%0A%20%20P3%20--%3E%20OK%0A%20%20P4%20--%3E%20OK%0A%20%20P5%20--%3E%20OK%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把预防写进配方流程。规模落点进<a href="/llm/pf2-pretrain-checklist">检查清单</a>时，强制附三行：本次 \\(D/N\\) 相对哪次拟合、本次数据制度（重复率、MoE 与否）与拟合制度差在哪、代理迁移的担保边界声明。缩放实验遵循<a href="/llm/scaling-law-fitting">拟合方法</a>的口径：清洗 warmup 与尖峰段、用有效数据 \\(D&#39;\\)、三种切片交叉验证谷底同侧、留出最大点不参与拟合。下游里程碑一律换算成损失或 FLOPs 口径再进预算文档——能力声明用多度量，预算规划用连续量。</p><p><span class="marginnote">Chinchilla 的三种估计（三项式、IsoFLOP 剖面、末点插值）在约四百次运行上交叉支撑同一个结论——单方法单切片的「缩放结论」在文献里可以差出很远；读到任何新系数，先问它用了几种切片。</span></p><p><span class="marginnote">数字实例：本次 8B 模型计划 400B token，\\(D/N=50\\)，明显偏离 20 的口诀——这时检查清单要求的三行声明就必须写明：依据哪次过训拟合、制度差在哪、推理侧省了什么；没有这三行，这个落点只是拍脑袋。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么这些失败反复出现：缩放律的每个系数都绑定一个隐式坐标系——架构、数据制度、日程形状、稳定件组合——而决策场景永远与新坐标系有出入。失败不是「律错了」，而是<strong>适用域判断缺失</strong>：20 这个数字在它自己的拟合制度内是对的，错的是搬到 MoE 或重复体制时不变。这也是为什么预防的组织形式是清单与声明而不是「更聪明的拟合」：拟合技术已经足够好，坏的是使用纪律。本课程的检查清单、重复记账、代理校验三处都在替这张失败清单执行拦截——缩放失败模式的真正解药散布在前面各课，本课只负责把它们并排点名。</p><p><span class="marginnote">常见误区：初学者容易把「涌现能力」当成可规划的里程碑，算准某天分数跳崖。实际上不少悬崖是阈值化度量（对了算对、错了算零）画出来的；预算规划要用连续量（损失、FLOPs），别拿跳崖当里程碑。</span></p>',7)),(B(),A(t,null,{default:a(()=>[r(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E5%8F%A3%E8%AF%80%EF%BC%9A%E6%AF%8F%E5%8F%82%E6%95%B0%E7%BA%A6%2020%20token%22%5D%20--%3E%20S1%5B%22%E7%A8%A0%E5%AF%86%20%2B%20%E7%8B%AC%E7%89%B9%E6%95%B0%E6%8D%AE%20%2B%20%E6%97%A5%E7%A8%8B%E8%A1%B0%E5%87%8F%E5%88%B0%E4%BD%8D%22%5D%0A%20%20C%20--%3E%20S2%5B%22MoE%EF%BC%9A%E6%B4%BB%E8%B7%83%E5%8F%82%E8%BF%9C%E5%B0%8F%E4%BA%8E%E6%80%BB%E5%8F%82%22%5D%0A%20%20C%20--%3E%20S3%5B%22%E9%87%8D%E5%A4%8D%E4%BD%93%E5%88%B6%EF%BC%9A%E6%9C%89%E6%95%88%20D'%20%E7%BC%A9%E6%B0%B4%22%5D%0A%20%20C%20--%3E%20S4%5B%22%E8%BF%87%E8%AE%AD%E7%9B%AE%E6%A0%87%EF%BC%9A%E4%B8%BA%E6%8E%A8%E7%90%86%E6%95%88%E7%8E%87%E6%95%85%E6%84%8F%E5%81%8F%E7%A6%BB%22%5D%0A%20%20S1%20--%3E%20O1%5B%22%E5%8F%A3%E8%AF%80%E5%9C%A8%E5%85%B6%E6%8B%9F%E5%90%88%E5%9F%9F%E5%86%85%E6%88%90%E7%AB%8B%22%5D%0A%20%20S2%20--%3E%20O2%5B%22%E8%B0%B7%E5%BA%95%E7%A7%BB%E4%BD%8D%EF%BC%9A%E5%8F%A3%E8%AF%80%E5%A4%B1%E6%95%88%22%5D%0A%20%20S3%20--%3E%20O3%5B%22%E8%B0%B7%E5%BA%95%E7%A7%BB%E4%BD%8D%EF%BC%9A%E5%8F%A3%E8%AF%80%E5%A4%B1%E6%95%88%22%5D%0A%20%20S4%20--%3E%20O4%5B%22%E6%9C%89%E6%84%8F%E5%81%8F%E7%A6%BB%EF%BC%9A%E6%98%BE%E5%BC%8F%E5%86%B3%E7%AD%96%22%5D%0A%20%20O1%20--%3E%20Z%5B%22%E7%BC%BA%E9%80%82%E7%94%A8%E5%9F%9F%E5%A3%B0%E6%98%8E%EF%BC%8C%E6%89%8D%E6%98%AF%E5%A4%B1%E8%B4%A5%E6%A0%B9%E6%BA%90%22%5D%0A%20%20O2%20--%3E%20Z%0A%20%20O3%20--%3E%20Z%0A%20%20O4%20--%3E%20Z%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p>这张图回答的是「同一条口诀为什么在不同制度下时灵时不灵」：系数本身没错，错的是把绑定在某个制度上的拟合结论当成跨制度的常数使用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课清单针对预训练的规模与预算决策；推理侧的算力与部署规模是服务课程的对象。能力涌现的哲学争论——训练动态突变与度量伪影两根轴——在<a href="/llm/emergence-debate">涌现之争</a>已分头处理，本课只取其对预算规划的结论。架构标度（MoE 的总参与活跃参、词表与序列长的标度）在各自专课；本课把它们当「会移动谷底的制度变量」引用。最后一类边界：缩放律对「下一代」的预言力本身会衰减——数据制度剧变、目标函数更换时，旧拟合全面失效，此时唯一诚实的动作是小规模重拟合。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五类失败：日程耦合误读、系数常数化、指标悬崖规划、代理越界迁移、拟合吃脏点。</li><li>每个系数绑定隐式坐标系；失败源于适用域判断缺失，不是律本身错。</li><li>规模落点附三行声明：依据哪次拟合、制度差在哪、迁移边界在哪。</li><li>预算用损失与 FLOPs 口径，能力声明用多度量；两种语言不混写。</li><li>出处：Kaplan et al., 2020；Hoffmann et al., Training Compute-Optimal LLMs, 2022；Schaeffer, Miranda &amp; Koyejo, NeurIPS 2023。</li></ul>',5))])}const _=i(p,[["render",F]]);export{C as __pageData,_ as default};
